//! Start-page tutorial-video list, sourced from the official YouTube playlist.
//!
//! Native builds scan the playlist at boot and cache the result. Web builds
//! read a same-origin `videos.json` and thumbnails generated by the Pages
//! workflow, avoiding YouTube's browser CORS restrictions.

/// The official tutorials playlist.
pub const PLAYLIST_URL: &str =
    "https://youtube.com/playlist?list=PLZq_TEkIFh9bAnoOX1HiCAunm3anZDBOl";

const PLAYLIST_ID: &str = "PLZq_TEkIFh9bAnoOX1HiCAunm3anZDBOl";

/// One playlist entry, ready for the Start page.
#[derive(Clone, Debug, serde::Deserialize)]
pub struct VideoEntry {
    pub id: String,
    pub title: String,
    /// JPEG bytes of the thumbnail (from cache or the network), if available.
    #[serde(default)]
    pub thumb: Option<Vec<u8>>,
}

/// Whether `id` matches YouTube's canonical 11-character URL-safe base64 id format.
pub(crate) fn is_valid_video_id(id: &str) -> bool {
    id.len() == 11
        && id
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
}

/// Watch URL for one of the playlist's videos, keeping the playlist context.
pub fn watch_url(id: &str) -> String {
    if !is_valid_video_id(id) {
        return PLAYLIST_URL.to_string();
    }
    format!("https://www.youtube.com/watch?v={id}&list={PLAYLIST_ID}")
}

#[cfg(not(target_arch = "wasm32"))]
const UA: &str = concat!("OpenCADStudio/", env!("OCS_APP_VERSION"));

/// Directory of the on-disk thumbnail / listing cache.
#[cfg(not(target_arch = "wasm32"))]
fn cache_dir() -> Option<std::path::PathBuf> {
    crate::config::config_dir().map(|d| d.join("video_thumbs"))
}

/// Load the listing cached by the previous successful fetch — the instant,
/// offline-friendly Start-page state while the live fetch runs.
#[cfg(not(target_arch = "wasm32"))]
pub fn load_cached() -> Vec<VideoEntry> {
    let Some(dir) = cache_dir() else {
        return Vec::new();
    };
    let Ok(listing) = std::fs::read_to_string(dir.join("playlist.txt")) else {
        return Vec::new();
    };
    listing
        .lines()
        .filter_map(|line| {
            let (id, title) = line.split_once('\t')?;
            if !is_valid_video_id(id) || title.is_empty() {
                return None;
            }
            Some(VideoEntry {
                id: id.to_string(),
                title: title.to_string(),
                thumb: std::fs::read(dir.join(format!("{id}.jpg"))).ok(),
            })
        })
        .collect()
}

/// Fetch the playlist's current entries, in playlist order, refreshing the
/// on-disk cache. `Err` when offline or the page markup changes — the caller
/// keeps whatever [`load_cached`] provided.
#[cfg(not(target_arch = "wasm32"))]
pub fn fetch_playlist() -> Result<Vec<VideoEntry>, String> {
    let agent = crate::network::agent(std::time::Duration::from_secs(15));
    let page = agent
        .get(PLAYLIST_URL)
        .header("User-Agent", "Mozilla/5.0")
        .call()
        .map_err(|e| e.to_string())?
        .body_mut()
        .with_config()
        .limit(8 * 1024 * 1024)
        .read_to_string()
        .map_err(|e| e.to_string())?;

    // Ordered, de-duplicated video ids from the page's embedded JSON. The
    // `"videoId":"…"` pattern has been stable for years and doubles as the
    // canary: no matches → markup changed → keep the cached list.
    let mut ids: Vec<String> = Vec::new();
    let mut rest = page.as_str();
    while let Some(pos) = rest.find("\"videoId\":\"") {
        let start = pos + "\"videoId\":\"".len();
        let Some(end) = rest[start..].find('"') else {
            break;
        };
        let id = &rest[start..start + end];
        if is_valid_video_id(id) && !ids.iter().any(|k| k == id) {
            ids.push(id.to_string());
        }
        rest = &rest[start + end..];
        if ids.len() >= 50 {
            break;
        }
    }
    if ids.is_empty() {
        return Err("no videos found in playlist page".into());
    }

    let dir = cache_dir();
    if let Some(d) = &dir {
        let _ = std::fs::create_dir_all(d);
    }

    let next_index = std::sync::atomic::AtomicUsize::new(0);
    let slots: Vec<std::sync::Mutex<Option<VideoEntry>>> =
        (0..ids.len()).map(|_| std::sync::Mutex::new(None)).collect();
    let workers = ids.len().min(4);
    std::thread::scope(|scope| {
        for _ in 0..workers {
            scope.spawn(|| loop {
                let idx = next_index.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                let Some(id) = ids.get(idx) else {
                    break;
                };
                // Title via oEmbed — stable and key-less. A video without a title
                // (deleted / private) is skipped.
                let title = agent
                    .get(&format!(
                        "https://www.youtube.com/oembed?url=https://youtu.be/{id}&format=json"
                    ))
                    .header("User-Agent", UA)
                    .call()
                    .ok()
                    .and_then(|mut r| {
                        r.body_mut()
                            .with_config()
                            .limit(256 * 1024)
                            .read_to_string()
                            .ok()
                    })
                    .and_then(|body| {
                        serde_json::from_str::<serde_json::Value>(&body)
                            .ok()?
                            .get("title")?
                            .as_str()
                            .map(str::to_string)
                    });
                let Some(title) = title else {
                    continue;
                };

                // Thumbnail: cache first, else download once and store atomically.
                let cache_path = dir.as_ref().map(|d| d.join(format!("{id}.jpg")));
                let mut thumb = cache_path.as_ref().and_then(|p| std::fs::read(p).ok());
                if thumb.is_none() {
                    let fetched = agent
                        .get(&format!("https://i.ytimg.com/vi/{id}/mqdefault.jpg"))
                        .header("User-Agent", UA)
                        .call()
                        .ok()
                        .and_then(|mut r| {
                            r.body_mut()
                                .with_config()
                                .limit(2 * 1024 * 1024)
                                .read_to_vec()
                                .ok()
                        });
                    if let (Some(bytes), Some(p)) = (&fetched, &cache_path) {
                        if let Some(parent) = p.parent() {
                            let _ = std::fs::create_dir_all(parent);
                        }
                        let _ = crate::io::write_file_atomic(p, bytes);
                    }
                    thumb = fetched;
                }
                if let Ok(mut guard) = slots[idx].lock() {
                    *guard = Some(VideoEntry {
                        id: id.clone(),
                        title,
                        thumb,
                    });
                }
            });
        }
    });
    let mut out: Vec<VideoEntry> = slots
        .into_iter()
        .filter_map(|slot| slot.into_inner().ok().flatten())
        .collect();
    if out.is_empty() {
        return Err("no video titles resolved".into());
    }

    // The playlist page lists oldest-first; the Start page wants the newest
    // tutorials on top. Reversed before persisting, so the cached listing
    // (and every later offline launch) shares the same order.
    out.reverse();

    // Persist the listing atomically so the next launch starts from it.
    if let Some(d) = &dir {
        let _ = std::fs::create_dir_all(d);
        let listing: String = out
            .iter()
            .map(|v| format!("{}\t{}\n", v.id, v.title.replace(['\t', '\n'], " ")))
            .collect();
        let _ = crate::io::write_file_atomic(&d.join("playlist.txt"), listing.as_bytes());
    }
    Ok(out)
}

#[cfg(target_arch = "wasm32")]
pub async fn fetch_playlist_web() -> Result<Vec<VideoEntry>, String> {
    use wasm_bindgen::JsCast;
    use wasm_bindgen_futures::JsFuture;

    let window = web_sys::window().ok_or("no window")?;
    let response = JsFuture::from(window.fetch_with_str("videos.json"))
        .await
        .map_err(|_| "videos.json fetch failed")?
        .dyn_into::<web_sys::Response>()
        .map_err(|_| "videos.json response is invalid")?;
    if !response.ok() {
        return Err(format!("videos.json HTTP {}", response.status()));
    }
    let text = JsFuture::from(
        response
            .text()
            .map_err(|_| "videos.json text() unavailable")?,
    )
    .await
    .map_err(|_| "videos.json body read failed")?;
    let body = text.as_string().ok_or("videos.json body is not a string")?;
    let mut entries: Vec<VideoEntry> =
        serde_json::from_str(&body).map_err(|error| error.to_string())?;
    entries.retain(|entry| is_valid_video_id(&entry.id) && !entry.title.trim().is_empty());
    if entries.is_empty() {
        return Err("videos.json contains no videos".into());
    }

    let thumbnails = iced::futures::future::join_all(
        entries
            .iter()
            .map(|entry| fetch_thumbnail_web(entry.id.clone())),
    )
    .await;
    for (entry, thumbnail) in entries.iter_mut().zip(thumbnails) {
        entry.thumb = thumbnail.ok();
    }
    Ok(entries)
}

#[cfg(target_arch = "wasm32")]
async fn fetch_thumbnail_web(id: String) -> Result<Vec<u8>, String> {
    let local = format!("video_thumbs/{id}.jpg");
    match fetch_thumbnail_url(&local).await {
        Ok(bytes) => Ok(bytes),
        Err(_) => {
            // Local development uses the checked-in JSON snapshot without
            // binary thumbnails. YouTube's image CDN explicitly permits CORS,
            // so it is a safe fallback; deployed Pages builds use local files.
            fetch_thumbnail_url(&format!("https://i.ytimg.com/vi/{id}/mqdefault.jpg")).await
        }
    }
}

#[cfg(target_arch = "wasm32")]
async fn fetch_thumbnail_url(url: &str) -> Result<Vec<u8>, String> {
    use wasm_bindgen::JsCast;
    use wasm_bindgen_futures::JsFuture;

    let window = web_sys::window().ok_or("no window")?;
    let response = JsFuture::from(window.fetch_with_str(url))
        .await
        .map_err(|_| "thumbnail fetch failed")?
        .dyn_into::<web_sys::Response>()
        .map_err(|_| "thumbnail response is invalid")?;
    if !response.ok() {
        return Err(format!("thumbnail HTTP {}", response.status()));
    }
    let buffer = JsFuture::from(
        response
            .array_buffer()
            .map_err(|_| "thumbnail arrayBuffer() unavailable")?,
    )
    .await
    .map_err(|_| "thumbnail body read failed")?;
    Ok(js_sys::Uint8Array::new(&buffer).to_vec())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn video_id_validation_rejects_injection_and_traversal() {
        assert!(is_valid_video_id("dQw4w9WgXcQ"));
        assert!(is_valid_video_id("A_b-1234567"));
        assert!(!is_valid_video_id("../evil/jpg"));
        assert!(!is_valid_video_id("abc&x=12345"));
        assert!(!is_valid_video_id("short"));
        assert!(!is_valid_video_id("waytoolong12"));
        assert_eq!(watch_url("../evil/jpg"), PLAYLIST_URL);
        assert_eq!(
            watch_url("dQw4w9WgXcQ"),
            "https://www.youtube.com/watch?v=dQw4w9WgXcQ&list=PLZq_TEkIFh9bAnoOX1HiCAunm3anZDBOl"
        );
    }
}
